//! ADR-0037: with the `tauri` feature this generates the plugin's command
//! permissions (`permissions/autogenerated/`) and the ACL manifest; without
//! it (CI's headless build of the pure half) it does nothing.

#[cfg(feature = "tauri")]
const COMMANDS: &[&str] = &["open", "list", "close"];

fn main() {
    #[cfg(feature = "tauri")]
    tauri_plugin::Builder::new(COMMANDS).build();
}
